require_once __DIR__.'/../core/Auth.php';require_once __DIR__.'/../core/Response.php';require_once __DIR__.'/../lib/DocsRepository.php';Auth::requireLogin();if(!Auth::isAdmin()&&!Auth::isEmployee()&&!Auth::can('docs.view')){http_response_code(403);exit('دسترسی غیرمجاز است.');}$pageTitle='مستندات و آموزش من';$adminExtraStylesheets=['/assets/css/workforce.css'];$q=trim((string)($_GET['q']??''));$category=(int)($_GET['category_id']??0);$items=DocsRepository::visible(['q'=>$q,'category_id'=>$category]);$categories=DocsRepository::categories(true);require __DIR__.'/../views/partials/admin-header.php';?>
<div class="workforce-head"><div><h1>مستندات و آموزش</h1><p>راهنماها و فایل‌های قابل مشاهده برای شما</p></div></div><section class="card"><form method="get" class="form-actions"><input name="q" value="<?=e($q)?>" placeholder="جستجو در مستندات"><select name="category_id"><option value="">همه دسته‌ها</option><?php foreach($categories as $c):?><option value="<?=$c['id']?>" <?=$category===$c['id']?'selected':''?>><?=e($c['title'])?></option><?php endforeach?></select><button class="btn btn-primary">جستجو</button></form></section><div class="doc-card-grid"><?php foreach($items as $i):?><article class="card doc-card"><div class="doc-meta"><span><?=e($i['category_title']?:'عمومی')?></span><?php if($i['require_read_confirmation']):?><span>نیازمند تایید مطالعه</span><?php endif?></div><h2><?=e($i['title'])?></h2><p><?=e($i['summary'])?></p><a class="btn btn-primary" href="/employee/doc-view.php?id=<?=$i['id']?>">مطالعه مستند</a></article><?php endforeach?><?php if(!$items):?><section class="card">مستندی مطابق دسترسی شما پیدا نشد.</section><?php endif?></div><?php require __DIR__.'/../views/partials/admin-footer.php';?>
